/// Sanitized helper-side facts returned by `REPORT_STREAM_STATE`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct P234JavaAcceptState {
    accept_requested: u64,
    accept_entered: u64,
    accept_returned: u64,
    socket_stored: u64,
    accept_errors: u64,
    accepting: bool,
    accepted_count: u64,
    connected_count: u64,
    socket_surface_entered: u64,
    socket_surface_ready: u64,
    socket_surface_errors: u64,
}

fn p234_parse_java_accept_state(line: &str) -> Option<P234JavaAcceptState> {
    let mut fields = line.split_whitespace();
    if fields.next()? != "STREAM_STATUS" {
        return None;
    }
    let mut state = P234JavaAcceptState::default();
    let mut seen = 0u16;
    for field in fields {
        let (key, value) = field.split_once('=')?;
        match key {
            "accept_requested" => state.accept_requested = value.parse().ok()?,
            "accept_entered" => state.accept_entered = value.parse().ok()?,
            "accept_returned" => state.accept_returned = value.parse().ok()?,
            "socket_stored" => state.socket_stored = value.parse().ok()?,
            "accept_errors" => state.accept_errors = value.parse().ok()?,
            "accepting" => state.accepting = value.parse().ok()?,
            "accepted_count" => state.accepted_count = value.parse().ok()?,
            "connected_count" => state.connected_count = value.parse().ok()?,
            "socket_surface_entered" => state.socket_surface_entered = value.parse().ok()?,
            "socket_surface_ready" => state.socket_surface_ready = value.parse().ok()?,
            "socket_surface_errors" => state.socket_surface_errors = value.parse().ok()?,
            // Plan 236 adds source-lock and response-stage fields to the same
            // bounded line. Plan 234/235 intentionally retain their strict
            // eleven-field shape and ignore only these namespaced additions.
            key if key.starts_with("java_") => continue,
            _ => return None,
        }
        seen = seen.saturating_add(1);
    }
    (seen == 11).then_some(state)
}

type P235JavaResponseState = P234JavaAcceptState;

fn p235_parse_java_response_state(line: &str) -> Option<P235JavaResponseState> {
    p234_parse_java_accept_state(line)
}

